public class ArrayInitialization {
    public static void main(String[] args) {
        int[] scores = new int[5];          // elements default to 0
        System.out.println(scores[0]);      // 0

        String[] names = {"Alice", "Bob"};  // size inferred = 2
        System.out.println(names.length);   // 2

        Object[] objs = new Object[3];      // object array defaults to null
        System.out.println(objs[0]);        // null

        printArray(new int[]{10, 20, 30});  // anonymous array argument
    }

    static void printArray(int[] arr) {
        for (int v : arr) System.out.println(v);
    }
}
