import java.util.Arrays;

public class ArraysUtilityDemo {
    public static void main(String[] args) {
        int[] numbers = {5, 2, 8, 1, 9};
        Arrays.sort(numbers);                         // in-place sort
        System.out.println(Arrays.toString(numbers)); // [1, 2, 5, 8, 9]
        System.out.println(Arrays.binarySearch(numbers, 5)); // 2 (array must be sorted)

        int[] expanded = Arrays.copyOf(numbers, 7);   // pads with defaults
        System.out.println(Arrays.toString(expanded)); // [1, 2, 5, 8, 9, 0, 0]

        int[] a = {1, 2, 3}, b = {1, 2, 3};
        System.out.println(a == b);            // false (different objects)
        System.out.println(Arrays.equals(a, b)); // true (same contents)
    }
}
