public class ArrayBoundsDemo {
    public static void main(String[] args) {
        int[] numbers = {10, 20, 30, 40, 50};
        int index = 3; // imagine this comes from user input
        if (index >= 0 && index < numbers.length) {
            System.out.println("Value: " + numbers[index]); // Value: 40
        } else {
            System.out.println("Invalid index: " + index);
        }

        int[] empty = new int[0];
        if (empty.length > 0) System.out.println(empty[0]); // guarded, never runs
    }
}
