public class JaggedArrayDemo {
    public static void main(String[] args) {
        String[][] customerOrders = {
            {"ORD-001", "ORD-002"},            // 2 orders
            {"ORD-003"},                        // 1 order
            {"ORD-004", "ORD-005", "ORD-006"}  // 3 orders
        };
        for (int i = 0; i < customerOrders.length; i++) {
            for (int j = 0; j < customerOrders[i].length; j++) { // each row's own length
                System.out.print(customerOrders[i][j] + " ");
            }
            System.out.println();
        }
    }
}
